export default function App({ family }) {
  const { records, loading, error, setRecord } = useAppData();
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');
  const [sentenceText, setSentenceText] = useState('');
  const [activeMemberId, setActiveMemberId] = useState(family.members[0]?.id || '');
  const [selectedRoundId, setSelectedRoundId] = useState('');

  const members = family.members || [];

  // Filter records that are story sentences
  const sentences = useMemo(() => {
    return records
      .filter(r => r.type === 'sentence' && r.roundId)
      .sort((a, b) => {
        const timeA = Number(a.createdAt) || 0;
        const timeB = Number(b.createdAt) || 0;
        if (timeA !== timeB) return timeA - timeB;
        return String(a.id).localeCompare(String(b.id));
      });
  }, [records]);

  // Group sentences by roundId
  const rounds = useMemo(() => {
    const map = new Map();
    for (const s of sentences) {
      if (!map.has(s.roundId)) {
        map.set(s.roundId, {
          roundId: s.roundId,
          title: s.roundTitle || 'Untitled Story',
          sentences: [],
          createdAt: s.createdAt
        });
      }
      map.get(s.roundId).sentences.push(s);
    }
    return Array.from(map.values()).sort((a, b) => (Number(b.createdAt) || 0) - (Number(a.createdAt) || 0));
  }, [sentences]);

  // Determine current active round
  const currentRound = useMemo(() => {
    if (!rounds.length) return null;
    if (selectedRoundId && rounds.find(r => r.roundId === selectedRoundId)) {
      return rounds.find(r => r.roundId === selectedRoundId);
    }
    return rounds[0];
  }, [rounds, selectedRoundId]);

  // Suggested member turn based on member order and sentence count
  const suggestedMember = useMemo(() => {
    if (!members.length || !currentRound) return members[0] || null;
    const count = currentRound.sentences.length;
    return members[count % members.length];
  }, [members, currentRound]);

  async function handleStartNewStory() {
    setSaving(true);
    setSaveError('');
    try {
      const newRoundId = crypto.randomUUID();
      const firstSentenceId = crypto.randomUUID();
      const starterMember = members[0] || { id: 'anon', name: 'Someone' };

      // We automatically seed the round with a title/opening or let user start first sentence
      await setRecord(firstSentenceId, {
        type: 'sentence',
        roundId: newRoundId,
        roundTitle: `Story #${rounds.length + 1}`,
        authorId: starterMember.id,
        authorName: starterMember.name,
        text: `Once upon a time in ${family.family || 'our family'}...`,
        createdAt: Date.now()
      });
      setSelectedRoundId(newRoundId);
    } catch (e) {
      setSaveError(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  async function handleAddSentence(e) {
    e.preventDefault();
    if (!sentenceText.trim() || !currentRound || saving || loading) return;

    setSaving(true);
    setSaveError('');
    try {
      const author = members.find(m => m.id === activeMemberId) || members[0] || { id: 'unknown', name: 'Family Member' };
      const newId = crypto.randomUUID();
      await setRecord(newId, {
        type: 'sentence',
        roundId: currentRound.roundId,
        roundTitle: currentRound.title,
        authorId: author.id,
        authorName: author.name,
        text: sentenceText.trim(),
        createdAt: Date.now()
      });
      setSentenceText('');

      // Advance suggested member turn automatically
      const nextIndex = (members.findIndex(m => m.id === author.id) + 1) % members.length;
      if (members[nextIndex]) {
        setActiveMemberId(members[nextIndex].id);
      }
    } catch (e) {
      setSaveError(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  return (
    <main style={{ padding: 20, maxWidth: 760, margin: '0 auto', display: 'grid', gap: 24, fontFamily: 'inherit' }}>
      <Section
        title="Story Relay"
        description="Collaborative family storytelling. Each person adds one sentence in turn!"
        actions={
          rounds.length > 0 ? (
            <Button variant="secondary" onClick={handleStartNewStory} busy={saving} disabled={loading}>
              ✨ New story
            </Button>
          ) : null
        }
      >
        {error || saveError ? (
          <Feedback kind="error" title="Could not save or load stories">
            {error || saveError}
          </Feedback>
        ) : null}

        {loading ? (
          <Feedback kind="loading" title="Loading stories…" />
        ) : rounds.length === 0 ? (
          <Feedback
            kind="empty"
            title="No stories yet"
            actions={
              <Button onClick={handleStartNewStory} busy={saving}>
                Start a story
              </Button>
            }
          >
            Create the first collaborative story round for your family.
          </Feedback>
        ) : (
          <div style={{ display: 'grid', gap: 20 }}>
            {/* Story selector tabs if multiple rounds exist */}
            {rounds.length > 1 && (
              <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4 }}>
                {rounds.map(r => (
                  <button
                    key={r.roundId}
                    onClick={() => setSelectedRoundId(r.roundId)}
                    className={currentRound?.roundId === r.roundId ? 'primary' : 'secondary'}
                    style={{ padding: '6px 12px', borderRadius: 8, fontSize: '0.9rem', whiteSpace: 'nowrap', cursor: 'pointer' }}
                  >
                    {r.title} ({r.sentences.length})
                  </button>
                ))}
              </div>
            )}

            {/* Current Active Story Card */}
            {currentRound && (
              <div className="surface" style={{ padding: 20, borderRadius: 12, border: '1px solid #e7eaee', background: '#fff', display: 'grid', gap: 16 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
                  <h3 style={{ margin: 0, fontSize: '1.2rem', color: '#1e1f20' }}>{currentRound.title}</h3>
                  <span style={{ fontSize: '0.85rem', color: '#69727e' }}>
                    {currentRound.sentences.length} sentence{currentRound.sentences.length === 1 ? '' : 's'}
                  </span>
                </div>

                {/* Full rendered story narrative view */}
                <div style={{ background: '#f7f8fa', padding: 16, borderRadius: 8, lineHeight: 1.7, color: '#1e1f20', fontSize: '1.05rem' }}>
                  {currentRound.sentences.map((s, idx) => (
                    <span key={s.id} title={`Added by ${s.authorName || 'Member'}`}>
                      {s.text}{' '}
                    </span>
                  ))}
                </div>

                {/* Sentence by sentence breakdown */}
                <div style={{ display: 'grid', gap: 8 }}>
                  <h4 style={{ margin: 0, fontSize: '0.95rem', color: '#69727e', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Contribution history</h4>
                  <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'grid', gap: 8 }}>
                    {currentRound.sentences.map(s => (
                      <li key={s.id} style={{ display: 'flex', justifyContent: 'space-between', gap: 12, fontSize: '0.95rem', padding: '8px 12px', background: '#fff', borderRadius: 6, border: '1px solid #e7eaee' }}>
                        <span style={{ color: '#1e1f20' }}>{s.text}</span>
                        <span style={{ color: '#69727e', whiteSpace: 'nowrap', fontSize: '0.85rem' }}>— {s.authorName || 'Member'}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            )}

            {/* Turn indicator & Pass-the-device picker */}
            <div className="surface" style={{ padding: 20, borderRadius: 12, border: '1px solid #e7eaee', background: '#fff', display: 'grid', gap: 16 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                <div style={{ display: 'grid', gap: 4 }}>
                  <span style={{ fontSize: '0.85rem', color: '#69727e', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Suggested Turn</span>
                  <strong style={{ fontSize: '1.1rem', color: '#0659fd' }}>
                    👉 {suggestedMember ? suggestedMember.name : 'Anyone'}
                  </strong>
                </div>

                {members.length > 0 && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                    <label htmlFor="active-member" style={{ fontSize: '0.9rem', fontWeight: 500, color: '#69727e' }}>Who is holding device:</label>
                    <select
                      id="active-member"
                      value={activeMemberId}
                      onChange={e => setActiveMemberId(e.target.value)}
                      style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #e7eaee', background: '#fff', fontSize: '0.95rem', color: '#1e1f20' }}
                    >
                      {members.map(m => (
                        <option key={m.id} value={m.id}>
                          {m.name} ({m.role})
                        </option>
                      ))}
                    </select>
                  </div>
                )}
              </div>

              {/* Add sentence form */}
              <form onKeyDown={event=>{if(event.key==='Enter' && event.target.tagName==='INPUT'){event.preventDefault();if(event.currentTarget.reportValidity())event.currentTarget.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));}}} onSubmit={handleAddSentence} style={{ display: 'grid', gap: 16, borderTop: '1px solid #e7eaee', paddingTop: 16 }}>
                <Field
                  id="sentence-input"
                  label={`Your sentence (${members.find(m => m.id === activeMemberId)?.name || 'Member'})`}
                  value={sentenceText}
                  onChange={e => setSentenceText(e.target.value)}
                  placeholder="Type the next sentence of the story..."
                  hint="Keep it brief and fun! Honor-system family play."
                />
                <div>
                  <Button type="submit" busy={saving} disabled={loading || !sentenceText.trim()}>
                    {saving ? 'Adding…' : 'Add sentence'}
                  </Button>
                </div>
              </form>
            </div>
          </div>
        )}
      </Section>
    </main>
  );
}

import { useState } from 'react';
import { useAppData } from '@kin/app';

const ROWS = 6;
const COLS = 7;

function Section({ title, description, actions, children }) {
  return (
    <section style={{ display: 'grid', gap: 24, minWidth: 0 }}>
      <header style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap' }}>
        <div style={{ display: 'grid', gap: 8, minWidth: 0 }}>
          <h2 style={{ margin: 0, fontSize: 20 }}>{title}</h2>
          {description && <p style={{ margin: 0, color: '#69727e', maxWidth: '65ch', fontSize: 14 }}>{description}</p>}
        </div>
        {actions && <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>{actions}</div>}
      </header>
      {children}
    </section>
  );
}

function Button({ children, variant = 'primary', busy = false, disabled = false, type = 'button', ...props }) {
  return (
    <button
      {...props}
      type={type === 'submit' ? 'button' : type} onClick={event=>{if(type==='submit'){event.preventDefault();const form=event.currentTarget.form;if(form?.reportValidity())form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));}else props.onClick?.(event);}}
      className={variant === 'primary' ? 'primary' : 'secondary'}
      disabled={disabled || busy}
      aria-busy={busy}
      style={{
        minHeight: 40,
        padding: '10px 16px',
        borderRadius: 10,
        fontWeight: 500,
        cursor: disabled || busy ? 'not-allowed' : 'pointer',
        ...props.style
      }}
    >
      {children}
    </button>
  );
}

function Feedback({ kind = 'empty', title, children, actions }) {
  return (
    <div
      role={kind === 'error' ? 'alert' : 'status'}
      style={{ display: 'grid', gap: 12, padding: '20px 0', borderTop: '1px solid #e7eaee', minWidth: 0 }}
    >
      <strong>{title}</strong>
      {children && <div style={{ color: '#69727e', lineHeight: 1.6, fontSize: 14 }}>{children}</div>}
      {actions && <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>{actions}</div>}
    </div>
  );
}

export default function App({ family }) {
  const { records, loading, error, setRecord, deleteRecord } = useAppData();
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');

  // Setup selected players
  const [nextPlayer1Id, setPlayer1Id] = useState(family.members[0]?.id || '');
  const [nextPlayer2Id, setPlayer2Id] = useState(family.members[1]?.id || family.members[0]?.id || '');
  const currentGame=records.find(r=>r.id==='current-game');
  const activeRoundId=currentGame?.roundId??'round-1';
  const player1Id=currentGame?.player1Id??nextPlayer1Id;
  const player2Id=currentGame?.player2Id??nextPlayer2Id;

  const members = family.members || [];
  const getMemberName = (id) => members.find(m => m.id === id)?.name || id || 'Player';

  // Extract moves for active round, sorted by moveIndex
  const roundMoves = records
    .filter(r => typeof r.roundId === 'string' && r.roundId === activeRoundId && typeof r.moveIndex === 'number')
    .sort((a, b) => a.moveIndex - b.moveIndex);

  // Reconstruct board & game state
  const board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
  let player1Symbol = 'A · Amber';
  let player2Symbol = 'B · Blue';

  let moveHistory = [];
  let winningLine = null;

  for (let i = 0; i < roundMoves.length; i++) {
    const move = roundMoves[i];
    const col = move.col;
    if (typeof col !== 'number' || col < 0 || col >= COLS) continue;

    // Find lowest empty row in this col
    let rowToFill = -1;
    for (let r = ROWS - 1; r >= 0; r--) {
      if (!board[r][col]) {
        rowToFill = r;
        break;
      }
    }

    if (rowToFill !== -1) {
      const piece = i % 2 === 0 ? 'P1' : 'P2';
      board[rowToFill][col] = piece;
      moveHistory.push({ row: rowToFill, col, piece, recordId: move.id });
    }
  }

  // Check winner
  function checkWin(currBoard) {
    // Horizontal
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c <= COLS - 4; c++) {
        const p = currBoard[r][c];
        if (p && p === currBoard[r][c+1] && p === currBoard[r][c+2] && p === currBoard[r][c+3]) {
          return { winner: p, line: [[r,c], [r,c+1], [r,c+2], [r,c+3]] };
        }
      }
    }
    // Vertical
    for (let r = 0; r <= ROWS - 4; r++) {
      for (let c = 0; c < COLS; c++) {
        const p = currBoard[r][c];
        if (p && p === currBoard[r+1][c] && p === currBoard[r+2][c] && p === currBoard[r+3][c]) {
          return { winner: p, line: [[r,c], [r+1,c], [r+2,c], [r+3,c]] };
        }
      }
    }
    // Diagonal down-right
    for (let r = 0; r <= ROWS - 4; r++) {
      for (let c = 0; c <= COLS - 4; c++) {
        const p = currBoard[r][c];
        if (p && p === currBoard[r+1][c+1] && p === currBoard[r+2][c+2] && p === currBoard[r+3][c+3]) {
          return { winner: p, line: [[r,c], [r+1,c+1], [r+2,c+2], [r+3,c+3]] };
        }
      }
    }
    // Diagonal up-right
    for (let r = 3; r < ROWS; r++) {
      for (let c = 0; c <= COLS - 4; c++) {
        const p = currBoard[r][c];
        if (p && p === currBoard[r-1][c+1] && p === currBoard[r-2][c+2] && p === currBoard[r-3][c+3]) {
          return { winner: p, line: [[r,c], [r-1,c+1], [r-2,c+2], [r-3,c+3]] };
        }
      }
    }
    return null;
  }

  const winResult = checkWin(board);
  const winner = winResult ? winResult.winner : null;
  winningLine = winResult ? winResult.line : null;
  const isDraw = !winner && moveHistory.length === ROWS * COLS;

  const currentTurnPlayerPiece = moveHistory.length % 2 === 0 ? 'P1' : 'P2';
  const currentTurnName = currentTurnPlayerPiece === 'P1' ? getMemberName(player1Id) : getMemberName(player2Id);

  async function handleDrop(col) {
    if (loading || saving || winner || isDraw) return;

    // Check if column is full
    if (board[0][col] !== null) return;

    setSaving(true);
    setSaveError('');
    try {
      if(!currentGame)await setRecord('current-game',{roundId:activeRoundId,player1Id,player2Id});
      const moveId = `${activeRoundId}-move-${moveHistory.length}`;
      await setRecord(moveId, {
        roundId: activeRoundId,
        moveIndex: moveHistory.length,
        col,
        player1Id,
        player2Id,
        createdAt: Date.now()
      });
    } catch (e) {
      setSaveError(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  async function handleNewGame() {
    setSaving(true);
    setSaveError('');
    try {
      const newRoundId = `round-${Date.now()}`;
      // Just switch activeRoundId to a brand new one
      await setRecord('current-game',{roundId:newRoundId,player1Id:nextPlayer1Id,player2Id:nextPlayer2Id});
    } catch (e) {
      setSaveError(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  async function handleUndo() {
    if (moveHistory.length === 0 || winner || isDraw || loading || saving) return;
    const lastMove = moveHistory[moveHistory.length - 1];
    setSaving(true);
    setSaveError('');
    try {
      await deleteRecord(lastMove.recordId);
    } catch (e) {
      setSaveError(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  return (
    <main style={{ padding: 20, maxWidth: 760, margin: '0 auto', display: 'grid', gap: 24, background: '#f7f8fa', color: '#1e1f20', fontFamily: 'inherit' }}>
      <Section
        title="Family Connect Four"
        description="Honor-system pass and play. Take turns dropping pieces into columns 1 through 7. Connect four in a row horizontally, vertically, or diagonally to win!"
        actions={
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <Button variant="secondary" onClick={handleUndo} disabled={loading || saving || moveHistory.length === 0 || !!winner || isDraw}>
              Undo Last Move
            </Button>
            <Button variant="primary" onClick={handleNewGame} busy={saving} disabled={loading}>
              New Game
            </Button>
          </div>
        }
      >
        {error || saveError ? (
          <Feedback kind="error" title="Could not complete move">
            {error || saveError}
          </Feedback>
        ) : null}

        {loading ? (
          <Feedback kind="loading" title="Loading game state…" />
        ) : (
          <div style={{ display: 'grid', gap: 16 }}>
            {/* Player Setup & Turn Bar */}
            <div className="surface" style={{ padding: 16, display: 'grid', gap: 12, borderRadius: 12, background: '#ffffff', border: '1px solid #e7eaee' }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, flexWrap: 'wrap' }}>
                <div style={{ display: 'grid', gap: 4 }}>
                  <label htmlFor="p1-select" style={{ fontSize: 13, fontWeight: 500, color: '#69727e' }}>
                    🟡 Amber Player (P1)
                  </label>
                  <select
                    id="p1-select"
                    value={nextPlayer1Id}
                    onChange={(e) => setPlayer1Id(e.target.value)}
                    style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #e7eaee', background: '#fff', fontSize: 14 }}
                  >
                    {members.map(m => (
                      <option key={m.id} value={m.id}>{m.name} ({m.role})</option>
                    ))}
                  </select>
                </div>
                <div style={{ display: 'grid', gap: 4 }}>
                  <label htmlFor="p2-select" style={{ fontSize: 13, fontWeight: 500, color: '#69727e' }}>
                    🔵 Blue Player (P2)
                  </label>
                  <select
                    id="p2-select"
                    value={nextPlayer2Id}
                    onChange={(e) => setPlayer2Id(e.target.value)}
                    style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #e7eaee', background: '#fff', fontSize: 14 }}
                  >
                    {members.map(m => (
                      <option key={m.id} value={m.id}>{m.name} ({m.role})</option>
                    ))}
                  </select>
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid #e7eaee', paddingTop: 12, flexWrap: 'wrap', gap: 8 }}>
                <div style={{ fontSize: 15, fontWeight: 600 }}>
                  {winner ? (
                    <span style={{ color: '#0659fd' }}>
                      Winner: {winner === 'P1' ? getMemberName(player1Id) : getMemberName(player2Id)} ({winner === 'P1' ? 'Amber' : 'Blue'})!
                    </span>
                  ) : isDraw ? (
                    <span style={{ color: '#69727e' }}>It's a draw! Board is full.</span>
                  ) : (
                    <span>
                      Current Turn: <strong style={{ color: currentTurnPlayerPiece === 'P1' ? '#d97706' : '#2563eb' }}>{currentTurnName} ({currentTurnPlayerPiece === 'P1' ? 'A · Amber' : 'B · Blue'})</strong>
                    </span>
                  )}
                </div>
                <div style={{ fontSize: 13, color: '#69727e' }}>
                  One player moves at a time (Honor System)
                </div>
              </div>
            </div>

            {/* Accessible Drop Controls */}
            <div style={{ display: 'grid', gridTemplateColumns: `repeat(${COLS}, minmax(0, 1fr))`, gap: 6 }}>
              {Array.from({ length: COLS }).map((_, c) => {
                const isFull = board[0][c] !== null;
                return (
                  <Button
                    key={`drop-${c}`}
                    variant="secondary"
                    onClick={() => handleDrop(c)}
                    disabled={loading || saving || !!winner || isDraw || isFull}
                    style={{ padding: '8px 4px', fontSize: 12, minHeight: 36 }}
                    aria-label={`Drop in column ${c + 1}`} title={`Drop piece in column ${c + 1}`}
                  >
                    Drop {c + 1}
                  </Button>
                );
              })}
            </div>

            {/* Game Board */}
            <div
              className="surface"
              style={{
                background: '#0659fd',
                padding: 12,
                borderRadius: 16,
                display: 'grid',
                gridTemplateRows: `repeat(${ROWS}, minmax(0, 1fr))`,
                gap: 8,
                boxShadow: '0 4px 12px rgba(6, 89, 253, 0.15)',
                minWidth: 0,
                width: '100%',
                boxSizing: 'border-box'
              }}
            >
              {board.map((row, rIdx) => (
                <div
                  key={`row-${rIdx}`}
                  style={{
                    display: 'grid',
                    gridTemplateColumns: `repeat(${COLS}, minmax(0, 1fr))`,
                    gap: 8
                  }}
                >
                  {row.map((cell, cIdx) => {
                    const isWinningPiece = winningLine && winningLine.some(([wr, wc]) => wr === rIdx && wc === cIdx);
                    let bg = '#ffffff';
                    let label = 'Empty slot';
                    if (cell === 'P1') {
                      bg = '#f59e0b'; // Amber
                      label = `Amber piece (${getMemberName(player1Id)})`;
                    } else if (cell === 'P2') {
                      bg = '#3b82f6'; // Blue
                      label = `Blue piece (${getMemberName(player2Id)})`;
                    }

                    return (
                      <div
                        key={`cell-${rIdx}-${cIdx}`}
                        aria-label={`Row ${rIdx + 1}, Col ${cIdx + 1}: ${label}`}
                        style={{
                          aspectRatio: '1',
                          background: bg,
                          borderRadius: '50%',
                          boxShadow: cell ? 'inset 0 2px 4px rgba(0,0,0,0.2)' : 'inset 0 2px 6px rgba(0,0,0,0.1)',
                          border: isWinningPiece ? '3px solid #ffffff' : 'none',
                          transform: isWinningPiece ? 'scale(1.05)' : 'none',
                          transition: 'transform 0.2s ease, background 0.2s ease',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          fontSize: 10,
                          fontWeight: 'bold',
                          color: '#fff'
                        }}
                      >
                        {cell === 'P1' ? '🟡' : cell === 'P2' ? '🔵' : ''}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>

            {/* Quick Rules & State Info */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', color: '#69727e', fontSize: 13, padding: '0 4px', flexWrap: 'wrap', gap: 8 }}>
              <span>Total Moves in Round: {moveHistory.length}</span>
              <span>Active Round ID: {activeRoundId}</span>
            </div>
          </div>
        )}
      </Section>
    </main>
  );
}

import { useState } from 'react';
import { useAppData } from '@kin/app';

const QUESTIONS = [
  { id: 1, text: 'What is 7 multiplied by 8?', options: ['54', '56', '64', '72'], correct: 1 },
  { id: 2, text: 'Which animal is known as the "Ship of the Desert"?', options: ['Horse', 'Elephant', 'Camel', 'Llama'], correct: 2 },
  { id: 3, text: 'How many planets are in our solar system?', options: ['7', '8', '9', '10'], correct: 1 },
  { id: 4, text: 'Which of these mammals can truly fly?', options: ['Flying squirrel', 'Bat', 'Sugar glider', 'Lemur'], correct: 1 },
  { id: 5, text: 'What is the closest star to Earth?', options: ['Sirius', 'Proxima Centauri', 'The Sun', 'Polaris'], correct: 2 },
];

function Section({ title, description, actions, children }) {
  return (
    <section style={{ display: 'grid', gap: 24, minWidth: 0 }}>
      <header style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap' }}>
        <div style={{ display: 'grid', gap: 8, minWidth: 0 }}>
          <h2 style={{ margin: 0, fontSize: 24, fontWeight: 700, color: '#1e1f20' }}>{title}</h2>
          {description && <p style={{ margin: 0, color: '#69727e', maxWidth: '65ch', lineHeight: 1.5 }}>{description}</p>}
        </div>
        {actions && <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'center' }}>{actions}</div>}
      </header>
      {children}
    </section>
  );
}

function Button({ children, variant = 'primary', busy = false, disabled = false, type = 'button', ...props }) {
  return (
    <button
      {...props}
      type={type === 'submit' ? 'button' : type} onClick={event=>{if(type==='submit'){event.preventDefault();const form=event.currentTarget.form;if(form?.reportValidity())form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));}else props.onClick?.(event);}}
      className={variant === 'primary' ? 'primary' : 'secondary'}
      disabled={disabled || busy}
      aria-busy={busy}
      style={{
        minHeight: 44,
        padding: '11px 19px',
        borderRadius: 10,
        fontWeight: 600,
        cursor: disabled || busy ? 'not-allowed' : 'pointer',
        border: variant === 'primary' ? 'none' : '1px solid #e7eaee',
        background: variant === 'primary' ? '#0659fd' : '#ffffff',
        color: variant === 'primary' ? '#ffffff' : '#1e1f20'
      }}
    >
      {children}
    </button>
  );
}

function Feedback({ kind = 'empty', title, children, actions }) {
  return (
    <div
      role={kind === 'error' ? 'alert' : 'status'}
      style={{
        display: 'grid',
        gap: 12,
        padding: '24px 20px',
        background: kind === 'error' ? '#fdf2f2' : '#f7f8fa',
        border: `1px solid ${kind === 'error' ? '#f8d7da' : '#e7eaee'}`,
        borderRadius: 12,
        minWidth: 0
      }}
    >
      <strong style={{ color: kind === 'error' ? '#9e302b' : '#1e1f20' }}>{title}</strong>
      {children && <div style={{ color: '#69727e', lineHeight: 1.6 }}>{children}</div>}
      {actions && <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>{actions}</div>}
    </div>
  );
}

export default function App({ family }) {
  const { records, loading, error, setRecord, deleteRecord } = useAppData();
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');

  const [selectedMemberId, setSelectedMemberId] = useState(family.members[0]?.id || '');




  const members = family.members || [];

  // Find current active round record or latest round
  const rounds = records.filter(r => r.type === 'round').sort((a,b)=>a.createdAt-b.createdAt || a.id.localeCompare(b.id));
  const activeRound = rounds.length ? rounds[rounds.length - 1] : null;

  async function startNewRound() {
    setSaving(true);
    setSaveError('');
    try {
      setReview(false);
      const newRoundId = `round_${crypto.randomUUID()}`;
      await setRecord(newRoundId, {
        type: 'round',
        createdAt: Date.now(),
        roundNumber: rounds.length + 1
      });
    } catch (e) {
      setSaveError(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  async function submitAnswer(optionIndex) {
    if (!activeRound || selectedOption !== null || saving) return;
    const currentQ = QUESTIONS[activeQuestionIndex];
    const isCorrect = optionIndex === currentQ.correct;


    setSaving(true);
    setSaveError('');
    try {
      const answerRecordId = `ans_${activeRound.id}_${selectedMemberId}_q${currentQ.id}`;
      await setRecord(answerRecordId, {
        type: 'answer',
        roundId: activeRound.id,
        memberId: selectedMemberId,
        questionId: currentQ.id,
        selectedOption: optionIndex,
        correct: isCorrect,
        answeredAt: Date.now()
      });
      setReview(true);
    } catch (e) {
      setSaveError(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  function nextQuestion() { setReview(false); }
  const [review,setReview]=useState(false);
  // Calculate scores for active round
  const roundAnswers = activeRound ? records.filter(r => r.type === 'answer' && r.roundId === activeRound.id) : [];

  const memberScores = members.map(m => {
    const mAnswers = roundAnswers.filter(a => a.memberId === m.id);
    const correctCount = mAnswers.filter(a => a.correct).length;
    const totalAnswered = mAnswers.length;
    return { member: m, correctCount, totalAnswered };
  });

  const answered=roundAnswers.filter(a=>a.memberId===selectedMemberId);
  const nextIndex=QUESTIONS.findIndex(q=>!answered.some(a=>a.questionId===q.id));
  const lastAnswer=[...answered].sort((a,b)=>b.answeredAt-a.answeredAt)[0];
  const activeQuestionIndex=review&&lastAnswer?QUESTIONS.findIndex(q=>q.id===lastAnswer.questionId):nextIndex<0?QUESTIONS.length:nextIndex;
  const currentQ = QUESTIONS[activeQuestionIndex];
  const currentMemberAnswer = activeRound && currentQ 
    ? roundAnswers.find(a => a.memberId === selectedMemberId && a.questionId === currentQ.id)
    : null;

  const selectedOption=currentMemberAnswer?.selectedOption??null;
  const answerFeedback=currentMemberAnswer?(currentMemberAnswer.correct?'Correct!':`The correct answer was: ${currentQ.options[currentQ.correct]}`):null;

  return (
    <main style={{ padding: 20, maxWidth: 760, margin: '0 auto', display: 'grid', gap: 24, fontFamily: 'Figtree, sans-serif', color: '#1e1f20' }}>
      <Section
        title="Family Trivia"
        description="Pass-and-play trivia game with 5 family-friendly questions. Answer turn-by-turn and see who wins!"
        actions={
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {!activeRound && (
              <Button busy={saving} disabled={loading || !!error} onClick={startNewRound}>
                Start quiz
              </Button>
            )}
            {activeRound && (
              <Button variant="secondary" busy={saving} disabled={loading || !!error} onClick={startNewRound}>
                New round
              </Button>
            )}
          </div>
        }
      >
        {error || saveError ? (
          <Feedback kind="error" title="Could not load or save game data">
            {error || saveError}
          </Feedback>
        ) : null}

        {loading ? (
          <Feedback kind="loading" title="Loading trivia records…" />
        ) : !activeRound ? (
          <Feedback kind="empty" title="No active trivia round">
            Ready to test your knowledge? Click "Start quiz" above to begin.
          </Feedback>
        ) : (
          <div style={{ display: 'grid', gap: 20, minWidth: 0 }}>
            {/* Member picker & Round info */}
            <div className="surface" style={{ padding: 16, borderRadius: 12, display: 'grid', gap: 12, border: '1px solid #e7eaee', background: '#ffffff' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                <div>
                  <span style={{ fontSize: 13, fontWeight: 600, color: '#69727e', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                    Round #{activeRound.roundNumber || 1}
                  </span>
                  <h3 style={{ margin: '4px 0 0 0', fontSize: 18 }}>Current Player</h3>
                </div>
                <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
                  <label htmlFor="member-select" style={{ fontWeight: 600, fontSize: 14 }}>Playing as:</label>
                  <select
                    id="member-select"
                    value={selectedMemberId}
                    onChange={e => {
                      setSelectedMemberId(e.target.value); setReview(false);
                    }}
                    style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #e7eaee', background: '#fff', fontSize: 14 }}
                  >
                    {members.map(m => (
                      <option key={m.id} value={m.id}>{m.name} ({m.role})</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* Quiz active / finished state */}
            {activeQuestionIndex < QUESTIONS.length ? (
              <div className="surface" style={{ padding: 24, borderRadius: 12, display: 'grid', gap: 20, border: '1px solid #e7eaee', background: '#ffffff' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontWeight: 600, color: '#0659fd' }}>
                    Question {activeQuestionIndex + 1} of {QUESTIONS.length}
                  </span>
                  <span style={{ fontSize: 13, color: '#69727e' }}>Honor system turn-based play</span>
                </div>

                <h3 style={{ margin: 0, fontSize: 20, lineHeight: 1.4 }}>{currentQ.text}</h3>

                <div style={{ display: 'grid', gap: 10, gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))' }}>
                  {currentQ.options.map((opt, idx) => {
                    const alreadyAnsweredThisQ = !!currentMemberAnswer;
                    const isSelected = currentMemberAnswer ? currentMemberAnswer.selectedOption === idx : selectedOption === idx;
                    const isThisCorrect = idx === currentQ.correct;

                    let bg = '#ffffff';
                    let borderColor = '#e7eaee';
                    let textColor = '#1e1f20';

                    if (alreadyAnsweredThisQ || selectedOption !== null) {
                      if (isThisCorrect) {
                        bg = '#e6f4ea';
                        borderColor = '#34a853';
                        textColor = '#137333';
                      } else if (isSelected) {
                        bg = '#fce8e6';
                        borderColor = '#ea4335';
                        textColor = '#c5221f';
                      }
                    }

                    return (
                      <button
                        key={idx}
                        disabled={alreadyAnsweredThisQ || selectedOption !== null || saving}
                        onClick={() => submitAnswer(idx)}
                        style={{
                          padding: '16px',
                          borderRadius: 10,
                          border: `2px solid ${borderColor}`,
                          background: bg,
                          color: textColor,
                          textAlign: 'left',
                          fontWeight: 600,
                          fontSize: 15,
                          cursor: alreadyAnsweredThisQ || selectedOption !== null || saving ? 'default' : 'pointer',
                          transition: 'all 0.2s ease'
                        }}
                      >
                        {String.fromCharCode(65 + idx)}. {opt}
                      </button>
                    );
                  })}
                </div>

                {(answerFeedback || currentMemberAnswer) && (
                  <div style={{ display: 'grid', gap: 12, paddingTop: 8 }}>
                    <div style={{ padding: 12, borderRadius: 8, background: '#f7f8fa', border: '1px solid #e7eaee', fontWeight: 600 }}>
                      {answerFeedback || (currentMemberAnswer?.correct ? 'Correct!' : `Incorrect. The correct answer was: ${currentQ.options[currentQ.correct]}`)}
                    </div>
                    <div>
                      <Button onClick={nextQuestion}>
                        {activeQuestionIndex === QUESTIONS.length - 1 ? 'View Final Scores' : 'Next Question →'}
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="surface" style={{ padding: 24, borderRadius: 12, display: 'grid', gap: 20, border: '1px solid #e7eaee', background: '#ffffff' }}>
                <h3 style={{ margin: 0, fontSize: 22 }}>Round Complete! 🎉</h3>
                <p style={{ margin: 0, color: '#69727e' }}>Here are the final scores for this round:</p>

                <div style={{ display: 'grid', gap: 12 }}>
                  {memberScores.map(({ member, correctCount, totalAnswered }) => (
                    <div key={member.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 16px', borderRadius: 8, background: '#f7f8fa', border: '1px solid #e7eaee' }}>
                      <span style={{ fontWeight: 600 }}>{member.name} ({member.role})</span>
                      <span style={{ fontWeight: 700, color: '#0659fd' }}>{correctCount} / {QUESTIONS.length} correct</span>
                    </div>
                  ))}
                </div>

                <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', paddingTop: 8 }}>
                  <Button onClick={startNewRound} busy={saving}>
                    Start New Round
                  </Button>
                </div>
              </div>
            )}

            {/* Leaderboard summary card */}
            <div className="surface" style={{ padding: 20, borderRadius: 12, display: 'grid', gap: 12, border: '1px solid #e7eaee', background: '#ffffff' }}>
              <h4 style={{ margin: 0, fontSize: 16 }}>Live Round Scoreboard</h4>
              <div style={{ display: 'grid', gap: 8 }}>
                {memberScores.map(({ member, correctCount, totalAnswered }) => (
                  <div key={member.id} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 14, color: '#69727e' }}>
                    <span>{member.name}</span>
                    <span>{totalAnswered} answered ({correctCount} correct)</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </Section>
    </main>
  );
}
